import json

CLASSES = sorted(['True','False','Unknown'])

with open('data/proofwriter_full.json') as f:
    pw = json.load(f)
gt = {p['id']: p['answer'] for p in pw}

# Check all generators
sources = {
    'Mistral': ('data/mistral_pw600_sc_votes.json', 'vote_dict'),
    'Qwen2.5-14B': ('results/exp032_qwen25_14b_pw600/results.json', 'results_list'),
    'Qwen3-14B': ('results/exp033_qwen3_14b_pw600_nonthinking/results.json', 'results_list'),
    'LLaMA-8B': ('results/exp048_llama8b_pw600/exp048_results.json', 'results_list'),
}

for name, (path, fmt) in sources.items():
    with open(path) as f:
        raw = json.load(f)

    votes_dict = {}
    precomputed = {}
    if fmt == 'results_list':
        for r in raw['results']:
            pid = r['problem_id']
            votes_dict[pid] = r['sc_vote_distribution']
            if 'sc_answer' in r:
                precomputed[pid] = r['sc_answer']
    elif fmt == 'vote_dict':
        for pid, counts in raw.items():
            votes_dict[pid] = {'True': counts[0], 'False': counts[1], 'Unknown': counts[2]}

    # Recompute with D061 tiebreaking
    recomp_correct = 0
    precomp_correct = 0
    discrepancies = 0
    for pid in votes_dict:
        v = votes_dict[pid]
        max_v = max(v.get(c,0) for c in CLASSES)
        tied = [c for c in CLASSES if v.get(c,0) == max_v]
        d061_ans = sorted(tied)[0]
        if d061_ans == gt.get(pid):
            recomp_correct += 1
        if pid in precomputed:
            if precomputed[pid] == gt.get(pid):
                precomp_correct += 1
            if precomputed[pid] != d061_ans:
                discrepancies += 1

    total = len(votes_dict)
    line = f'{name}: D061={recomp_correct}/{total}={recomp_correct/total*100:.2f}%'
    if precomputed:
        line += f', precomputed={precomp_correct}/{total}={precomp_correct/total*100:.2f}%, discrepancies={discrepancies}'
    else:
        line += ' (no precomputed sc_answer)'
    print(line)
"
